import torch


def q058(shadow, model, decay):
    if not 0 <= decay <= 1:
        raise ValueError("invalid decay")
    with torch.no_grad():
        source = dict(model.named_parameters())
        for name, p in shadow.named_parameters():
            p.lerp_(source[name], 1 - decay)
        buffers = dict(model.named_buffers())
        for name, b in shadow.named_buffers():
            b.copy_(buffers[name])
    return shadow
